CREATE TABLE IF NOT EXISTS practice_users (id uuid PRIMARY KEY, username text NOT NULL UNIQUE, nickname text NOT NULL, role text NOT NULL CHECK(role IN ('student','teacher','admin')), password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS practice_sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES practice_users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS practice_classes (id uuid PRIMARY KEY, name text NOT NULL, teacher_id uuid REFERENCES practice_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS practice_enrollments (class_id uuid REFERENCES practice_classes(id), student_id uuid REFERENCES practice_users(id), PRIMARY KEY(class_id,student_id));
CREATE TABLE IF NOT EXISTS practice_attempts (id uuid PRIMARY KEY, owner_id text NOT NULL, owner_kind text NOT NULL CHECK(owner_kind IN ('user','guest')), exam_id text NOT NULL, exam_version text NOT NULL, answers jsonb NOT NULL DEFAULT '{}', writing jsonb NOT NULL DEFAULT '{}', result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS practice_one_draft ON practice_attempts(owner_id,exam_id,exam_version) WHERE submitted_at IS NULL;
CREATE TABLE IF NOT EXISTS practice_rankings (student_id uuid REFERENCES practice_users(id), exam_id text NOT NULL, exam_version text NOT NULL, attempt_id uuid UNIQUE REFERENCES practice_attempts(id), reading_score numeric NOT NULL, listening_score numeric NOT NULL, total_score numeric NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(student_id,exam_id,exam_version));
CREATE TABLE IF NOT EXISTS practice_reviews (id uuid PRIMARY KEY, attempt_id uuid UNIQUE REFERENCES practice_attempts(id), student_id uuid REFERENCES practice_users(id), content_hash text NOT NULL, status text NOT NULL CHECK(status IN ('pending','processing','completed','failed')), model text NOT NULL, rubric_version text NOT NULL, original jsonb, teacher_override jsonb, error_code text, retries integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS practice_review_audit (id uuid PRIMARY KEY, review_id uuid REFERENCES practice_reviews(id), teacher_id uuid REFERENCES practice_users(id), previous_value jsonb, new_value jsonb NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS practice_limits (bucket text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS practice_settings (name text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO practice_settings(name,value) VALUES ('daily_ai_limit','10') ON CONFLICT DO NOTHING;
